const updateMeetVoiceSettings = `-- name: UpdateMeetVoiceSettings :one
UPDATE meet_voice_settings SET paused=$1, restrict_to_posts=$2, allowed_post_ids=$3, monthly_minutes_limit=$4
WHERE singleton=true RETURNING singleton, paused, last_tick_at, restrict_to_posts, allowed_post_ids, monthly_minutes_limit
`

