const voiceReportAllowed = `-- name: VoiceReportAllowed :one
SELECT EXISTS(SELECT 1 FROM meet_voice_reservations r
JOIN meet_voice_participants reporter ON reporter.id=r.id
JOIN meet_voice_participants target ON target.id=$1::uuid AND target.room_sid=reporter.room_sid
WHERE r.user_id=$2::uuid AND target.post_id=$3::uuid
  AND target.user_id<>r.user_id AND target.id<>r.id)
`

type VoiceReportAllowedParams struct {
	TargetID uuid.UUID `json:"target_id"`
	UserID   uuid.UUID `json:"user_id"`
	PostID   uuid.UUID `json:"post_id"`
}

func (q *Queries) VoiceReportAllowed(ctx context.Context, arg VoiceReportAllowedParams) (bool, error) {
	row := q.db.QueryRow(ctx, voiceReportAllowed, arg.TargetID, arg.UserID, arg.PostID)
	var exists bool
	err := row.Scan(&exists)
	return exists, err
}
